import { COMMUNITY_GOALS_POOL } from "../store/communityGoals";
import { getBuildingById } from "./villageActions";

export function updateCommunityNeeds(world, addLog) {
    const needs = world.communityNeeds;

    for (const [key, n] of Object.entries(needs)) {
        // dérive naturelle (entropie du monde)
        n.value -= n.decay;

        // influence des agents et du terrain
        if (key === 'food') {
            const stock = world.resources.filter(r => r.type === 'animal' || r.type === 'baies').length;
            n.value += stock * 0.0005; // plus il y a de nourriture, mieux on se porte
        }

        if (key === "confort") {
            const agents = world.agents || [];
            if (agents.length > 0) {
                let totalEnergy = 0;
                let totalBonheur = 0;

                for (const a of agents) {
                    totalEnergy += a.energy ?? 50;
                    totalBonheur += a.bonheur ?? 50;
                }

                const avgEnergy = totalEnergy / agents.length;
                const avgBonheur = totalBonheur / agents.length;

                // Base : plus les habitants sont fatigués ou peu heureux, plus le besoin de confort monte
                const inconfortPhysique = 1 - avgEnergy / 100;
                const inconfortEmotionnel = 1 - avgBonheur / 100;
                // qualite des batiments publics
                const dortoir = world.buildings.find(b=>b.id==='dortoir');
                const placeCentrale = world.buildings.find(b=>b.id==='centre');
              
                n.value+=(dortoir.level*0.03);
                n.value+=(placeCentrale.level*0.01);
                // Influence de l’environnement matériel
                n.value -= (inconfortPhysique * 0.04 + inconfortEmotionnel * 0.03);

                // Clamp
                n.value = Math.max(0, Math.min(1, n.value));
            }
        }

        if (key === 'ecology') {
            n.value += world.resources.length * 0.0001; // plus de diversité = équilibre écologique
        }
        if (key === "fiesta" || key === "religion") {
            const agents = world.agents || [];
            if (agents.length > 0) {
                let totalBonheur = 0;
                let totalEnergy = 0;

                for (const a of agents) {
                    totalBonheur += a.bonheur ?? 50;
                    totalEnergy += a.energy ?? 50;
                }

                const avgBonheur = totalBonheur / agents.length;
                const avgEnergy = totalEnergy / agents.length;

                if (key === "religion") {
                    // Plus le bonheur collectif est bas, plus le besoin religieux augmente.
                    // Une société en détresse cherche du sens.
                    const manqueDeSens = 1 - avgBonheur / 100;
                    n.value -= manqueDeSens * 0.005; // influence directe du moral global
                }

                if (key === "fiesta") {
                    // La fiesta naît de la fatigue et du désespoir — ou du trop plein d’énergie.
                    // Si tout le monde est à bout, l’envie de relâcher la pression augmente.
                    const fatigue = 1 - avgEnergy / 100;
                    const tristesse = 1 - avgBonheur / 100;
                    const envieDeFete = (fatigue * 0.6 + tristesse * 0.4);
                    n.value -= envieDeFete * 0.007;
                }
            }
        }

        // clamp entre 0 et 1
        n.value = Math.max(0, Math.min(1, n.value));
    }

    // Déclenchement d'événements collectifs
    const log = checkCommunityEvents(world);
    if(log!=null)
        addLog(log);
}
function checkCommunityEvents(world) {
  if (world.activeCommunityGoal) return null;

  for (const [key, n] of Object.entries(world.communityNeeds)) {
    if (n.value < 0.3) {
      // cherche tous les goals répondant à ce besoin
      const candidates = COMMUNITY_GOALS_POOL.filter(g =>
        g.category === key &&
        !world.completedCommunityGoals?.includes(g.id) &&
        (g.requires ?? []).every(r => world.completedCommunityGoals?.includes(r)) &&
        (!g.condition || g.condition(world))
      );

      if (candidates.length > 0) {
        const def=candidates[0];
        const goal =  {
            id: def.id,
            label: def.label,
            category: def.category,
            requiredResources: def.requiredResources,
            buildTime: def.buildTime,
            target:def.getTarget(world),
            progress: 0
        } ; // le plus prioritaire
        world.activeCommunityGoal = structuredClone(goal);
        return `⚠️ Nouveau projet communautaire : ${goal.label}`;
      }
    }
  }

  return null;
}

