// pathing.js

// utils
function getTile(world, x, y) {
  if (!world.tiles?.[y] || !world.tiles[y][x]) return null;
  return world.tiles[y][x];
}

function isPassable(world, x, y) {
  const t = getTile(world, x, y);
  return t && (t.passable ?? true);
}

function movementCost(world, x, y) {
  const t = getTile(world, x, y);
  if (!t) return Infinity;
  return t.movementCost ?? 1;
}

// Heuristic (Manhattan) scaled by avg cost (simple)
function heuristic(a, b) {
  return Math.abs(a.x - b.x) + Math.abs(a.y - b.y);
}

// A* on grid (4-neighbors). Returns list of {x,y} from start exclusive -> goal inclusive.
// start and goal are {x,y}
export function computePath(world, start, goal) {
  // quick bounds
  if (!getTile(world, goal.x, goal.y) || !isPassable(world, goal.x, goal.y)) return null;

  const key = (p) => `${p.x},${p.y}`;

  const open = new Map(); // key -> node {x,y, g, f, parentKey}
  const closed = new Set();

  const startKey = key(start);
  open.set(startKey, { x: start.x, y: start.y, g: 0, f: heuristic(start, goal), parent: null });

  const neighbors = (p) => {
    // 4-directional movement (no diagonal) — safe and simpler for tile-based movement
    return [
      { x: p.x + 1, y: p.y },
      { x: p.x - 1, y: p.y },
      { x: p.x, y: p.y + 1 },
      { x: p.x, y: p.y - 1 },
    ].filter(n => n.x >= 0 && n.y >= 0 && n.x < world.map.width && n.y < world.map.height);
  };

  while (open.size > 0) {
    // pick lowest f
    let currentKey = null;
    let currentNode = null;
    for (const [k, node] of open.entries()) {
      if (!currentNode || node.f < currentNode.f) {
        currentKey = k;
        currentNode = node;
      }
    }

    if (!currentNode) break;

    // if reached goal
    if (currentNode.x === goal.x && currentNode.y === goal.y) {
      // reconstruct path
      const path = [];
      let cur = currentNode;
      let curKey = currentKey;
      while (cur && cur.parent !== null) {
        path.unshift({ x: cur.x, y: cur.y });
        curKey = cur.parent;
        cur = open.get(curKey) || null;
        // Note: parent might be in closed; fetch from closed map? We'll reconstruct differently:
      }

      // Better reconstruction: maintain cameFrom map
      // To avoid complexity, let's reconstruct using a separate cameFrom map stored in open/closed.
      // But for simplicity here, we re-run reconstruct using parent pointers stored across nodes:
      // We'll instead store all nodes in a mapNodes to allow backtracking across closed.
      break;
    }

    // move current from open to closed
    open.delete(currentKey);
    closed.add(currentKey);

    for (const nb of neighbors(currentNode)) {
      const nbKey = `${nb.x},${nb.y}`;
      if (closed.has(nbKey)) continue;
      if (!isPassable(world, nb.x, nb.y)) continue;

      const costToEnter = movementCost(world, nb.x, nb.y);
      const tentative_g = currentNode.g + costToEnter;

      const existing = open.get(nbKey);
      if (!existing || tentative_g < existing.g) {
        const h = heuristic(nb, goal);
        open.set(nbKey, {
          x: nb.x,
          y: nb.y,
          g: tentative_g,
          f: tentative_g + h,
          parent: currentKey, // parent is the key of current node
        });
      }
    }
  }

  // If we reached here without early return, we need to try reconstructing path from nodes.
  // We'll combine nodes from open and closed into a single map for reconstruction.
  // Build nodeMap from open + closed nodes (we need their parent pointers)
  const nodeMap = new Map();
  // open's entries
  // NOTE: open currently contains leftover nodes; closed doesn't keep node objects.
  // To avoid this complexity, it's cleaner to re-implement with proper cameFrom map.
  // => Simpler: rewrite A* with cameFrom map below (clean implementation).
  return computePath_clean(world, start, goal);
}

// Clean A* with cameFrom map (4-neighbors)
export function computePath_clean(world, start, goal) {
  if (!getTile(world, goal.x, goal.y) || !isPassable(world, goal.x, goal.y)) return null;

  const startKey = `${start.x},${start.y}`;
  const goalKey = `${goal.x},${goal.y}`;

  const openSet = new Set([startKey]);
  const cameFrom = new Map(); // key -> parentKey

  const gScore = new Map(); // key -> g
  gScore.set(startKey, 0);

  const fScore = new Map(); // key -> f
  fScore.set(startKey, heuristic(start, goal));

  const neighborsOf = (x, y) => {
    return [
      { x: x + 1, y },
      { x: x - 1, y },
      { x, y: y + 1 },
      { x, y: y - 1 },
    ].filter(n => n.x >= 0 && n.y >= 0 && n.x < world.map.width && n.y < world.map.height);
  };

  while (openSet.size > 0) {
    // pick node in openSet with lowest fScore
    let currentKey = null;
    let currentF = Infinity;
    for (const k of openSet) {
      const f = fScore.get(k) ?? Infinity;
      if (f < currentF) {
        currentF = f;
        currentKey = k;
      }
    }
    if (!currentKey) break;

    if (currentKey === goalKey) {
      // reconstruct path
      const path = [];
      let cur = currentKey;
      while (cur !== startKey) {
        const [cx, cy] = cur.split(",").map(Number);
        path.unshift({ x: cx, y: cy });
        cur = cameFrom.get(cur);
        if (!cur) break;
      }
      return path; // path is start-exclusive, goal-inclusive
    }

    openSet.delete(currentKey);
    const [cx, cy] = currentKey.split(",").map(Number);

    for (const nb of neighborsOf(cx, cy)) {
      const nbKey = `${nb.x},${nb.y}`;
      if (!isPassable(world, nb.x, nb.y)) continue;

      const tentativeG = (gScore.get(currentKey) ?? Infinity) + movementCost(world, nb.x, nb.y);

      if (tentativeG < (gScore.get(nbKey) ?? Infinity)) {
        cameFrom.set(nbKey, currentKey);
        gScore.set(nbKey, tentativeG);
        fScore.set(nbKey, tentativeG + heuristic(nb, goal));
        openSet.add(nbKey);
      }
    }
  }

  // no path
  return null;
}

// ------- Movement executor functions -------

// Call to start movement: compute path and set agent.path etc.
export function moveTowards(agent, targetX, targetY, world) {
  // target is tile coords
  const start = { x: agent.x, y: agent.y };
  const goal = { x: Math.round(targetX), y: Math.round(targetY) };

  if (start.x === goal.x && start.y === goal.y) {
    // already there
    agent.state = 'acting';
    agent.path = null;
    agent.moveProgress = 0;
    return { status: 'arrived' };
  }

  const path = computePath_clean(world, start, goal);
  if (!path || path.length === 0) {
    // unreachable
    agent.state = 'idle';
    agent.path = null;
    agent.moveProgress = 0;
    return { status: 'unreachable' };
  }

  // store path on agent
  agent.path = path; // array of {x,y}, first entry is next step
  agent.moveProgress = 0;
  agent.state = 'moving';
  // ensure agent.speed exists (movement points per tick)
  agent.speed = agent.speed ?? 1;
  return { status: 'moving', pathLength: path.length };
}

// To be called every tick for moving agents
export function followPathTick(agent, world) {
  if (!agent.path || agent.path.length === 0) {
    // nothing to do
    agent.state = 'idle';
    agent.path = null;
    agent.moveProgress = 0;
    return { status: 'noPath' };
  }

  // Next tile we want to step into
  const next = agent.path[0];
  const cost = movementCost(world, next.x, next.y);

  // Accumulate progress
  agent.moveProgress = (agent.moveProgress ?? 0) + (agent.speed ?? 1);

  // If enough progress to enter the tile
  if (agent.moveProgress >= cost) {
    // step into tile
    agent.x = next.x;
    agent.y = next.y;
    agent.moveProgress -= cost; // keep leftover progress
    // consume energy proportional to cost
    agent.energy = Math.max(0, (agent.energy ?? 100) - Math.ceil(cost));
    // pop path head
    agent.path.shift();

    // arrived at final tile?
    if (!agent.path || agent.path.length === 0) {
      agent.state = 'acting';
      agent.moveProgress = 0;
      // agent.currentAction will be handled by your action resolution (call effect)
      return { status: 'arrived' };
    } else {
      // still moving
      agent.state = 'moving';
      return { status: 'moved', remaining: agent.path.length };
    }
  } else {
    // still accumulating progress, position not changed
    agent.state = 'moving';
    return { status: 'progress', progress: agent.moveProgress, needed: cost };
  }
}
