import {
  Box,
  Typography,
  Divider,
  Button,
  Collapse,
  IconButton,
  Stack,
} from "@mui/material";
import { useVillage } from "../../hooks/VillageContext"
import VillageLogPanel from "./VillageLog";
import CommunityMonitor from "./CommunityMonitor";
import { ExpandLess, ExpandMore } from "@mui/icons-material";
import { useState } from "react";
import MeteoWidget from "./MeteoWidget";

const VillageControl = ()=>{
const {world, togglePause, paused, reset} = useVillage();
   const [openMonitor, setOpenMonitor] = useState(false);
  const [openLog, setOpenLog] = useState(false);

  return (
    <Box
      sx={{
        width: 320,
        bgcolor: "#f4f5ef",
        display: "flex",
        flexDirection: "column",
        overflow: "auto",
        borderLeft: "2px solid #ccc",
        p: 2,
        gap: 2,
      }}
    >
      <Typography variant="h6">Panneau de contrôle</Typography>
      <Divider />

      <Stack direction="row" spacing={1}>
        <Button
          variant="contained"
          color={paused ? "error" : "primary"}
          onClick={togglePause}
          fullWidth
        >
          {paused ? "Redémarrer" : "Pause"}
        </Button>
        <Button
          variant="outlined"
          color="secondary"
          onClick={reset}
          fullWidth
        >
          Reset
        </Button>
      </Stack>
<MeteoWidget weather={world.weather}/>
      <Divider />

      <Typography variant="body2" color="text.secondary">
        Tick : <strong>{world.tick}</strong>
      </Typography>
      <Typography variant="body2" color="text.secondary">
        Agents : <strong>{world.agents.length}</strong>
      </Typography>

      <Divider />

      {/* --- Section Monitor --- */}
      <Box>
        <Stack direction="row" alignItems="center" justifyContent="space-between">
          <Typography variant="subtitle2">Community Monitor</Typography>
          <IconButton
            size="small"
            onClick={() => setOpenMonitor((v) => !v)}
          >
            {openMonitor ? <ExpandLess /> : <ExpandMore />}
          </IconButton>
        </Stack>
        <Collapse in={openMonitor} unmountOnExit>
          <Box sx={{ mt: 1 }}>
            <CommunityMonitor world={world} />
          </Box>
        </Collapse>
      </Box>

      {/* --- Section Log --- */}
      <Box>
        <Stack direction="row" alignItems="center" justifyContent="space-between">
          <Typography variant="subtitle2">Village Log</Typography>
          <IconButton
            size="small"
            onClick={() => setOpenLog((v) => !v)}
          >
            {openLog ? <ExpandLess /> : <ExpandMore />}
          </IconButton>
        </Stack>
        <Collapse in={openLog} unmountOnExit>
          <Box sx={{ mt: 1 }}>
            <VillageLogPanel />
          </Box>
        </Collapse>
      </Box>
    </Box>
  );
}

export default VillageControl;