import React, { createContext, useCallback, useContext, useEffect, useState } from "react";
import { initialWorld } from "../store/initialWorld";
import {  decideNextAction } from "../utils/villageActions";
import { ACTIONS } from "../store/vActions";
import { useLog } from "./LogContext";
import { updateCommunityNeeds } from "../utils/community";
import { generateOrganicTerrain, updateWeather } from "../utils/terrain";
import { followPathTick } from "../utils/deplacement";
import { populateWorld } from "../store/agents";

const VillageContext = createContext();



export const VillageProvider = ({ children }) => {
  const [world, setWorld] = useState(initialWorld);
  const { addLog } = useLog();
  const { paused, togglePause } = useTime();
  const reset = () => {
    generateOrganicTerrain(initialWorld);
    populateWorld(initialWorld)
    setWorld(initialWorld);
  }
  // demarrage

  useEffect(() => {
    reset();

  }, []);

  const worldTick = useCallback(() => {
    setWorld(prev => {
      const next = structuredClone(prev);

      updateCommunityNeeds(next, addLog);// rajoute world.activeCommunityGoal {type label} dont type=actionId?
      updateAgents(next, addLog);
      updateResources(next, addLog);

      next.tick += 1;
      return next;
    });
  }, []);

  useEffect(() => {
    if (paused) return;
    const interval = setInterval(worldTick, 1000 / 2); // 2 ticks/seconde
    return () => clearInterval(interval);
  }, [worldTick, paused]);

  return (
    <VillageContext.Provider value={{
      world, setWorld, togglePause, paused
      , reset
    }}>
      {children}
    </VillageContext.Provider>
  );
};

export const useVillage = () => useContext(VillageContext);

export const updateResources = (world, addLog) => {
  
  updateWeather(world);//"ensoleille", "pluie", "orage", "secheresse", "neige", "tempete"

  const { type } = world.weather;

  const weatherEffect = (resource) => {
    switch (type) {
      case "pluie":
        if (["baies", "verger", "champ"].includes(resource.type))
          return 1.4;
        return 1.1; // boost léger sur tout
      case "orage":
        if (Math.random() < 0.1) {
          return 0.5;
        }
        return 0.9;
      case "secheresse":
        if (["baies", "verger", "champ"].includes(resource.type))
          return 0.4;
        return 0.8;
      case "neige":
        if (["mine"].includes(resource.type))
          return 1.1;
        return 0.6;
      case "tempete":
        if (Math.random() < 0.15) {
          resource.quantite = Math.max(0, resource.quantite - resource.maxQuantite * 0.2);
        }
        return 0.7;
      default:
        return 1; // "ensoleille" ou inconnu
    }
  };

  const toRemove = [];

  for (const res of world.resources) {
    const mult = weatherEffect(res);
    const gain = (res.productivite || 0) * mult *0.1;

    res.quantite = Math.min(res.maxQuantite, Math.max(0, res.quantite + gain));

    // Cas de raréfaction extrême
    if (res.quantite <= 0) {
      if (Math.random() < 0.02) {
        addLog(`🚨 ${res.type} (${res.category}) a disparu (${res.id}) — épuisé !`);
        toRemove.push(res.id);
      } else if (Math.random() < 0.05) {
        // Éventuel signal visuel avant disparition
        addLog(`⚠️ ${res.type} (${res.category}) est presque épuisé (${Math.round(res.quantite)} restant)`);
      }
    }
  }

  // Suppression propre après boucle
  if (toRemove.length > 0) {
    world.resources = world.resources.filter(r => !toRemove.includes(r.id));
  
  }
};

const updateAgents = (world, addLog) => {
  let log = null;

  for (const agent of world.agents) {
    agent.hunger = Math.min(100,(agent.hunger??100)+1);
    agent.bonheur = Math.max(0,(agent.bonheur??0)-1);
    agent.energy = Math.max(0,(agent.energy??0)-1);
    if (agent.state === 'moving') {
      const res = followPathTick(agent, world);
      if (res.status === 'arrived') {
        // exécute l'action (agent.currentAction) maintenant qu'il est sur place
        log = ACTIONS[agent.currentAction?.name]?.effect?.(agent, world);
        if (log) addLog && addLog(log); // ou world.logEvent, addLog...
        agent.state = "acting";
      }
    } else if (agent.state === 'idle') {
      log = decideNextAction(agent, world);
      if (log) addLog && addLog(log);
    } else if (agent.state === 'acting') {
        const action = ACTIONS[agent.currentAction.name];
        if (action) {
          // Application du coût
          const cost = action.cost || {};
          if (cost.energy) agent.energy = Math.max(0, agent.energy - cost.energy);
          if (cost.bonheur) agent.bonheur = Math.max(0, agent.bonheur - cost.bonheur);
          if (cost.hunger) agent.hunger = Math.min(0, agent.hunger + cost.hunger);

          // Exécution de l'effet
          const addLog = action.effect(agent, world);
          log = `${agent.name} fait l'action ${agent.currentAction.name}: ${addLog || ''}`;
        }

        // Reset de l'état après l'action
        agent.state = "idle";
        agent.currentAction = null;
        agent.dest = null;
      }

  }

}
const useTime = () => {
  const [paused, setPaused] = useState(false);
  const togglePause = useCallback(() => setPaused(p => !p), []);
  const pause = useCallback(() => setPaused(true), []);
  const resume = useCallback(() => setPaused(false), []);
  return { paused, togglePause, pause, resume }
}