import React from "react";
import { Image, Circle, Text, Group } from "react-konva";
import imgLeonie from '../../../bitLife/images/F/adulte/avatar10.png';
import imgLapute from '../../../bitLife/images/F/adulte/pute.png';
import imgGerard from '../../../bitLife/images/M/adulte/avatar9.png';
import imgChef from '../../../bitLife/images/M/vieux/avatar13.png';
import imgMarc from '../../../bitLife/images/M/adulte/avatar14.png';
import { usePreloadedImages } from "../../../civ/utils/hooks";

const AgentSprite = ({ agent, images, cellSize }) => {


  const size = cellSize * 0.8;
  const centerX = (agent.x + 0.5) * cellSize;
  const centerY = (agent.y + 0.5) * cellSize;

 

  return (
    <Group>
      {images[agent.id] ? (
        <Image image={images[agent.id]} 
          x={centerX-cellSize/2}
          y={centerY-cellSize/2} 
          width={cellSize}
          height={cellSize}/>
      ) : (
        <Circle
          x={centerX}
          y={centerY}
          radius={cellSize / 3}
          fill={agent.color}
          shadowBlur={3}
        />
      )}

      <Text
        x={agent.x * cellSize-cellSize/2}
        y={(agent.y + 0.7) * cellSize-cellSize/2}
        text={agent.name}
        fontSize={10}
        width={cellSize}
        align="center"
        fill="#222"
      />

      <Text
        x={agent.x * cellSize}
        y={(agent.y + 1) * cellSize}
        text={agent.role}
        fontSize={9}
        width={cellSize}
        align="center"
        fill="#555"
      />
    </Group>
  );
};

const VillageAgents = ({ agents, cellSize }) => {
    const images = usePreloadedImages({gerard:imgGerard, leonie:imgLeonie
    , marc:imgMarc, chef:imgChef, pute:imgLapute})
  return (
    <>
      {agents.map((a) => (
        <AgentSprite key={a.id} agent={a} images={images} cellSize={cellSize} />
      ))}
    </>
  );
};

export default VillageAgents;