import { ACTIONS, distance } from "../store/vActions";
import { moveTowards } from "./deplacement";


export function decideNextAction(agent, world) {
  // On évalue les actions disponibles
  let log=null;
  const possible = Object.entries(ACTIONS)
   .filter(([_, def]) => (def.roles.includes(agent.role)||def.roles.includes('villageois')) 
        && def.conditions(agent, world))
    .map(([name, a]) => ({ name, score: a.desirability(agent,world), action: a }))
    .sort((a, b) => b.score - a.score);

  const best = possible[0];
  if (!best) return null;

  // Cherche une cible si besoin
  let target = null;
  if (best.action.findTarget)
    target = best.action.findTarget(agent, world);

  // Si une cible existe et qu’elle est éloignée, on déclenche un déplacement
  if (target && distance(agent, target) > 1) {
     const tx = target.x ?? agent.x;
        const ty = target.y ?? agent.y;
        const mv = moveTowards(agent, tx, ty, world);
        if (mv.status === 'unreachable') {
          // fallback: maybe choose another action or set state idle
          agent.state = 'idle';
        } else {
          agent.currentAction = { name: best.name, targetId: target.resourceId ?? null };

          agent.state = "moving";
          agent.dest =  target;
        }
    log=`${agent.name} va vers ${target.resourceId} pour faire ${best.name}`
  } else {
    // Action locale (manger, dormir…)
    agent.state = "acting";
    agent.currentAction = { name: best.name, targetId: target?.resourceId || null };
  }
}




export function nearby(agent, list, radius = 5, condition = () => true) {
  if (!list) return null;
  return list.find(item => distance(agent, item) <= radius && condition(item));
}

export function hasIngredients(agent, required = {}) {
  const inv = agent.inventory || {};
  return Object.entries(required).every(([res, qty]) => inv[res] >= qty);
}

export function average(obj) {
  const vals = Object.values(obj || {});
  return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : 50;
}


// Trouve la ressource animale la plus proche d'un agent
export function findTarget(agent, world, action) {
  let closest = null;
let skonCherche=[];
  if (action == 'chasser'){    
   skonCherche = world.resources.filter(r => r.type === 'animal' && r.quantite > 0);
  }
  if (action == 'baies'){    
   skonCherche = world.resources.filter(r => r.type === 'baies' && r.quantite > 0);
  }
  if (action == 'centre'){    
   skonCherche = world.buildings.filter(r => r.id === 'centre');
  }
  if (action == 'mine'){    //todo
   skonCherche = world.resources.filter(r => r.type === 'mine' && r.quantite > 0);
  }
  if (action == 'bois'){    //todo
   skonCherche = world.resources.filter(r => r.type === 'bois' && r.quantite > 0);
  }
  if (skonCherche.length === 0) return null;

  let minDist = Infinity;

  for (const res of skonCherche) {
    const dx = res.x - agent.x;
    const dy = res.y - agent.y;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (dist < minDist) {
      minDist = dist;
      closest = res;
    }
  
  }

  return closest ? { x: closest.x, y: closest.y, resourceId: closest.id } : null;
}

export function getBuildingById(world, buildingId){
  const bds = world.buildings.find(r => r.id === buildingId);
  return bds;

}
export function getBestLocation(agent, world, types = ['pampa', 'prairie']) {
  let best = null;
  let bestDist = Infinity;

  // Par défaut, on se base sur le centre du village
  if (!agent) agent = getBuildingById(world, 'centre');

  // Petite fonction utilitaire pour vérifier si une case est libre
  const isOccupied = (x, y) => {
    // Vérifie les bâtiments multi-cases
    for (const b of world.buildings) {
      const bw = b.width ?? 1;
      const bh = b.height ?? 1;
      if (x >= b.x && x < b.x + bw && y >= b.y && y < b.y + bh) {
        return true;
      }
    }
    // Vérifie les ressources sur la case exacte
    for (const r of world.resources) {
      if (r.x === x && r.y === y) return true;
    }
    return false;
  };

  // Balayage de la carte
  for (let y = 0; y < world.map.height; y++) {
    for (let x = 0; x < world.map.width; x++) {
      const t = world.tiles[y][x];
      if (types.includes(t.type) && !isOccupied(x, y)) {
        const d = Math.hypot(agent.x - x, agent.y - y);
        if (d < bestDist) {
          bestDist = d;
          best = { x, y };
        }
      }
    }
  }

  return best;
}

export function modifyResourceById(world, targetId, qteToAdd) {
  if (!targetId || qteToAdd === 0) return;

  // Cherche d'abord dans les ressources
  const res = world.resources.find(r => r.id === targetId);
  if (res) {
    res.quantite = Math.max(0, (res.quantite ?? 0) + (qteToAdd*5));
    return;
  }

  // Sinon, cherche dans les bâtiments
  const building = world.buildings.find(b => b.id === targetId);
  if (building) {
    // Les bâtiments n’ont pas toujours une “quantité”,
    // mais certains peuvent produire ou stocker des ressources
    if (!building.stock) building.stock = {};
    building.stock.food = (building.stock.food ?? 0) + qteToAdd;
    return;
  }

  // Enfin, regarde si c’est un agent (ex: un troc ou un don)
  const agent = world.agents.find(a => a.id === targetId);
  if (agent) {
    agent.inventory.food = Math.max(0, (agent.inventory.food ?? 0) + qteToAdd);
    return;
  }

  console.warn(`modifyResourceById: cible ${targetId} introuvable.`);
}
